import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))
    M = max(a) + 1 if a else 2
    M = max(M, 2)
    spf = list(range(M + 1))
    i = 2
    while i * i <= M:
        if spf[i] == i:
            for j in range(i * i, M + 1, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1
    omega = [0] * (M + 1)
    for v in range(2, M + 1):
        omega[v] = omega[v // spf[v]] + 1
    x = 0
    for v in a:
        x ^= omega[v]
    print("Anna" if x != 0 else "Bruno")

main()

