def syts(shape):
    # generate all SYT of shape as list of rows, values 1..n
    n=sum(shape)
    res=[]
    rows=[[] for _ in shape]
    def rec(v):
        if v>n:
            res.append([r[:] for r in rows]);return
        for i in range(len(shape)):
            if len(rows[i])<shape[i] and (i==0 or len(rows[i-1])>len(rows[i])):
                rows[i].append(v); rec(v+1); rows[i].pop()
    rec(1)
    return res
def insert(T,x):
    T=[r[:] for r in T]
    r=0
    while True:
        if r==len(T): T.append([x]);return T,r
        row=T[r]
        # find smallest > x
        j=None
        for k,y in enumerate(row):
            if y>x: j=k;break
        if j is None:
            row.append(x);return T,(r,len(row)-1)
        row[j],x=x,row[j]
        r+=1
def count(A,B):
    shape=[A]*(B-1)+[A-1]
    cnt=0;tot=0
    for T in syts(shape):
        # relabel values to 1..n, gaps at half integers: x in 0..n (x=k+0.5 means between k and k+1)
        n=A*B-1
        ok=False
        for g in range(n+1):
            # values shifted: P values v -> v if v<=g else v+1; x = g+0.5 -> g+1
            Tn=[[v if v<=g else v+1 for v in r] for r in T]
            T2,pos=insert(Tn,g+1)
            if pos==(B-1,A-1): ok=True
        cnt+=ok
    return cnt,len(syts(shape))
