import time
def solve(A,B,M):
    N=A*B-1
    lam=tuple([A]*(B-1)+[A-1])
    # f over partitions inside lam via memo: f(mu)=sum f(mu - corner)
    from functools import lru_cache
    @lru_cache(None)
    def F(mu):
        if sum(mu)==0: return 1
        s=0
        for r in range(B):
            if mu[r]>0 and (r==B-1 or mu[r]>mu[r+1]):
                nm=list(mu); nm[r]-=1
                s+=F(tuple(nm))
        return s%M
    V=0
    cur={(lam,0,None):1}
    for k in range(N,0,-1):
        nxt={}
        for (mu,c1,ph2),w in cur.items():
            for r in range(B):
                if mu[r]==0 or (r<B-1 and mu[r]==mu[r+1]): continue
                l=r+1
                nph2=ph2; ok=True
                if ph2 is not None and l==B-1-ph2:
                    if ph2+1==B-1: ok=False
                    else: nph2=ph2+1
                if not ok: continue
                if l==B and ph2 is None: nph2=0
                nc1=c1
                if l<=B-1 and l==B-1-c1:
                    nc1=c1+1
                nm=list(mu); nm[r]-=1; nm=tuple(nm)
                if nc1==B-1:
                    V=(V+w*F(nm))%M
                    continue
                key=(nm,nc1,nph2)
                nxt[key]=(nxt.get(key,0)+w)%M
        cur=nxt
    return F(lam)*V%M, V
