import sys, heapq

def solve_case(M, boxes):
    n = len(boxes)
    if M == 1:
        return max(0, sum(max(0, V - P) for V, P in boxes))
    b = sorted(boxes, key=lambda x: -x[0])
    suf = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suf[i] = suf[i + 1] + max(0, b[i][0] - b[i][1])
    k = M - 2
    best = 0
    heap = []
    sumP = 0
    for p in range(n):
        if len(heap) == k:
            V, P = b[p]
            val = (M - 1) - P - sumP + suf[p + 1]
            if val > best:
                best = val
        if k > 0:
            heapq.heappush(heap, -b[p][1])
            sumP += b[p][1]
            if len(heap) > k:
                sumP -= -heapq.heappop(heap)
    return best

def main():
    data = sys.stdin.buffer.read().split()
    pos = 0
    T = int(data[pos]); pos += 1
    out = []
    for _ in range(T):
        N = int(data[pos]); M = int(data[pos + 1]); pos += 2
        boxes = []
        for i in range(N):
            V = int(data[pos]); P = int(data[pos + 1]); pos += 2
            boxes.append((V, P))
        out.append(str(solve_case(M, boxes)))
    sys.stdout.write("\n".join(out) + "\n")

main()

