import sys, random
from functools import lru_cache
def solve(M, boxes, S=12, D=30):
    @lru_cache(None)
    def f(r, d):
        if d == 0: return 0
        res = None
        lst0 = list(r)
        for t in sorted(set(r)):
            lst = lst0[:]; idx = lst.index(t)
            opts = []
            if t > 0:
                nl = lst[:]; nl[idx] -= 1
                opts.append(1 + f(tuple(sorted(nl)), d-1))
            for (V,P) in boxes:
                if sum(r) + V - 1 > S: continue
                nl = lst[:]; nl[idx] += V-1
                opts.append(1 - P + f(tuple(sorted(nl)), d-1))
            v = max(opts + [0])
            res = v if res is None else min(res, v)
        return max(0, res)
    return f(tuple([0]*M), D)
