def hyp(M,boxes):
    n=len(boxes); best=0
    if n<M: return 0
    idx=range(n)
    for T in itertools.combinations(idx,M):
        rest=[i for i in idx if i not in T]
        gain_T=sum(1-boxes[i][1] for i in T)+min(boxes[i][0]-1 for i in T)
        fullg=sum(max(0,boxes[i][0]-boxes[i][1]) for i in rest)
        best=max(best,gain_T+fullg)
    return best
