            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD
        # reach[m]: operations to reach 1 starting from m
        reach = [0] * (N + 1)
        for m in range(2, N + 1):
            reach[m] = 1 + reach[bin(m).count('1')]
        good = [c for c in range(1, L + 1) if reach[c] <= k - 1]
