import sys
import numpy as np
def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    grid = data[1:1+n]
    letters = sorted(set(ch for row in grid for ch in row if ch != '-'))
    mats = []
    for c in letters:
        M = np.zeros((n, n), dtype=np.float32)
        for i in range(n):
            row = grid[i]
            for j in range(n):
                if row[j] == c:
                    M[i, j] = 1.0
        mats.append(M)
    T1 = np.zeros((n, n), dtype=bool)
    for i in range(n):
        for j in range(n):
            if grid[i][j] != '-':
                T1[i, j] = True
    settled = np.zeros((n, n), dtype=bool)
    ans = np.full((n, n), -1, dtype=np.int64)
    levels = []
    v = 0
    while True:
        new = np.zeros((n, n), dtype=bool)
        if v == 0:
            new |= np.eye(n, dtype=bool)
        if v == 1:
            new |= T1
        if v >= 2 and levels[v-2].any():
            F = levels[v-2].astype(np.float32)
            G = np.zeros((n, n), dtype=bool)
            for M in mats:
                G |= (M @ F @ M) > 0.5
            new |= G
        new &= ~settled
        settled |= new
        ans[new & (ans == -1)] = v
        levels.append(new)
        if v >= 2 and not levels[v-1].any() and not levels[v].any():
            break
        if v > 20000:
            break
        v += 1
    out = []
    for i in range(n):
        out.append(' '.join(str(int(ans[i, j])) for j in range(n)))
    print('\n'.join(out))
main()

