import sys
from functools import lru_cache

def solve(A, D=100):
    @lru_cache(maxsize=None)
    def G(d, Cs, Es):
        if d == 0 or (not Cs and not Es):
            return 0
        best = None
        for p in (0, 1):
            const = sum(1 for e in Es if (p + e) % 2 == 1)
            nC = []; nE = []
            for b in Cs:
                if (p + b) % 2 == 0:
                    nC.append((p + b) // 2)
                else:
                    nE.append((p + b - 1) // 2)
            v = const + G(d - 1, tuple(sorted(nC)), tuple(sorted(nE)))
            best = v if best is None else max(best, v)
        return best
    return G(D, tuple(sorted(A)), ())

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    A = [int(x) for x in data[1:1 + n]]
    print(solve(A, 100))

main()

