import sys

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    rows = [0] * n
    for i in range(m):
        u = int(data[2 + 2 * i]) - 1
        v = int(data[3 + 2 * i]) - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u
    rank = 0
    pivcols = []
    for c in range(n):
        r = None
        for i in range(rank, n):
            if (rows[i] >> c) & 1:
                r = i
                break
        if r is None:
            continue
        rows[rank], rows[r] = rows[r], rows[rank]
        for i in range(n):
            if i != rank and (rows[i] >> c) & 1:
                rows[i] ^= rows[rank]
        pivcols.append(c)
        rank += 1
    pivset = set(pivcols)
    basis = []
    for f in range(n):
        if f in pivset:
            continue
        x = 1 << f
        for i, p in enumerate(pivcols):
            if (rows[i] >> f) & 1:
                x |= 1 << p
        basis.append(x)
    cover = 0
    for b in basis:
        cover |= b
