class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid); m = len(grid[0])
        dirs = [(1,1),(1,-1),(-1,-1),(-1,1)]  # clockwise order
        def order(di, dj):
            rows = range(n-1,-1,-1) if di == 1 else range(n)
            cols = range(m-1,-1,-1) if dj == 1 else range(m)
            return rows, cols
        F0 = []
        for di, dj in dirs:
            F = [[0]*m for _ in range(n)]
            rows, cols = order(di, dj)
            for i in rows:
                gi = grid[i]; Fi = F[i]
                for j in cols:
                    v = gi[j]
                    if v == 0 or v == 2:
                        req = 2 if v == 0 else 0
                        ni, nj = i+di, j+dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == req:
                            Fi[j] = 1 + F[ni][nj]
                        else:
                            Fi[j] = 1
            F0.append(F)
        F1 = []
        for k, (di, dj) in enumerate(dirs):
            F = [[0]*m for _ in range(n)]
            ck = (k+1) % 4
            cdi, cdj = dirs[ck]
            F0c = F0[ck]
            rows, cols = order(di, dj)
            for i in rows:
                gi = grid[i]; Fi = F[i]
                for j in cols:
                    v = gi[j]
                    if v == 0 or v == 2:
                        req = 2 if v == 0 else 0
                        best = 0
                        ni, nj = i+di, j+dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == req:
                            best = F[ni][nj]
                        ni, nj = i+cdi, j+cdj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == req:
                            if F0c[ni][nj] > best:
                                best = F0c[ni][nj]
                        Fi[j] = 1 + best
                    else:
                        Fi[j] = 1
            F1.append(F)
        ans = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    ans = max(ans, 1)
                    for k, (di, dj) in enumerate(dirs):
                        ni, nj = i+di, j+dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 2:
                            ans = max(ans, 1 + F1[k][ni][nj])
        return ans

