from functools import lru_cache
from math import factorial
from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        @lru_cache(maxsize=None)
        def cnt(o, e, f):
            # parity strings with o odds, e evens, no two adjacent equal, first parity f (0=odd,1=even)
            if o + e == 0:
                return 1
            if f == 0:
                if o == 0:
                    return 0
                return cnt(o - 1, e, 1)
            else:
                if e == 0:
                    return 0
                return cnt(o, e - 1, 0)

        def ways(o, e, f):
            return cnt(o, e, f) * factorial(o) * factorial(e)

        no = (n + 1) // 2
        ne = n // 2
        total = ways(no, ne, 0) + ways(no, ne, 1)
        if k > total:
            return []

        remaining = list(range(1, n + 1))
        res = []
        prev = None  # parity of previous element
        for _ in range(n):
            chosen = None
            for idx, v in enumerate(remaining):
                par = v % 2
                if prev is not None and par == prev:
                    continue
                o = sum(1 for x in remaining if x % 2 == 1)
                e = len(remaining) - o
                if par == 1:
                    o -= 1
                else:
                    e -= 1
                w = ways(o, e, 1 - par) if (o + e) > 0 else 1
                if k <= w:
                    chosen = idx
                    break
                k -= w
            v = remaining.pop(chosen)
            res.append(v)
            prev = v % 2
        return res

