class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        w = []
        for i in range(h):
            j = n - 1 - i
            if i == j:
                w.append(pow(10, i, k))
            else:
                w.append((pow(10, i, k) + pow(10, j, k)) % k)
        full = (1 << k) - 1
        suf = [0] * (h + 1)
        suf[h] = 1
        for i in range(h - 1, -1, -1):
            lo = 1 if i == 0 else 0
            nxt = suf[i + 1]
            m = 0
            for d in range(lo, 10):
                sh = (d * w[i]) % k
                rot = ((nxt << sh) | (nxt >> (k - sh))) & full if sh else nxt
                m |= rot
            suf[i] = m
        if not (suf[0] & 1):
            return ""
        t = 0
        digits = []
        for i in range(h):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                r = (t - d * w[i]) % k
                if (suf[i + 1] >> r) & 1:
                    digits.append(str(d))
                    t = r
                    break
        s = ''.join(digits)
        return s + s[:n // 2][::-1]

