class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        a = nums; n = len(a)
        g = [n]*n
        st = []
        for i in range(n-1, -1, -1):
            while st and a[st[-1]] <= a[i]:
                st.pop()
            g[i] = st[-1] if st else n
            st.append(i)
        W = [0]*(n+1)
        for i in range(n-1, -1, -1):
            W[i] = a[i]*(g[i]-i) + W[g[i]]
        pre = [0]*(n+1)
        for i in range(n):
            pre[i+1] = pre[i] + a[i]
        sp = [list(range(n))]
        j = 1
        while (1 << j) <= n:
            prev = sp[-1]
            half = 1 << (j-1)
            cur = []
            for i in range(n - (1 << j) + 1):
                x = prev[i]; y = prev[i+half]
                if a[y] > a[x]:
                    cur.append(y)
                else:
                    cur.append(x)
            sp.append(cur)
            j += 1
        def argmax(l, r):
            length = r - l + 1
            t = length.bit_length() - 1
            x = sp[t][l]; y = sp[t][r - (1 << t) + 1]
            if a[y] > a[x]:
                return y
            return x
        def cost(l, r):
            q = argmax(l, r)
            return (W[l] - W[q]) + a[q]*(r+1-q) - (pre[r+1] - pre[l])
        ans = 0
        L = 0
        for r in range(n):
            while L <= r and cost(L, r) > k:
                L += 1
            ans += r - L + 1
        return ans

