from fractions import Fraction as F
def solve(N,K):
    M=N-K+1
    states=[(a,b) for a in range(1,N+1) for b in range(a+1,N+1)]
    idx={s:i for i,s in enumerate(states)}
    n=len(states)
    A=[[F(0)]*(n+1) for _ in range(n)]
    for (a,b) in states:
        i=idx[(a,b)]
        A[i][i]+=1
        for w in range(1,M+1):
            ca= w<=a<=w+K-1; cb= w<=b<=w+K-1
            p=F(1,M)
            if ca and cb: continue
            if not ca and not cb:
                A[i][i]-=p
            elif ca:
                for c in range(w,w+K):
                    A[i][idx[(c,b)]]-=p/K
            else:
                for d in range(w,w+K):
                    A[i][idx[(a,d)]]-=p/K
    # gauss
    for c in range(n):
        piv=next(r for r in range(c,n) if A[r][c]!=0)
        A[c],A[piv]=A[piv],A[c]
        pv=A[c][c]
        A[c]=[x/pv for x in A[c]]
        for r in range(n):
            if r!=c and A[r][c]!=0:
                f=A[r][c]
                A[r]=[x-f*y for x,y in zip(A[r],A[c])]
    return {s:A[idx[s]][n] for s in states}
