    hs=pref(S); ht=pref(T)
    def lcp(i,j):
        mx=min(n-i,m-j)
        lo,hi=0,mx
        while lo<hi:
            mid=(lo+hi+1)//2
            if (hs[i+mid]-hs[i]*pw[mid])%M==(ht[j+mid]-ht[j]*pw[mid])%M: lo=mid
            else: hi=mid-1
        return lo
    prev={}
    for d in range(K+1):
        cur={}
        for k in range(-d,d+1):
            if d==0:
                cands=[0]
            else:
                cands=[]
                if k in prev: cands.append(prev[k]+1)
                if k-1 in prev: cands.append(prev[k-1])
                if k+1 in prev: cands.append(prev[k+1]+1)
            if not cands: continue
            i=max(cands)
            i=min(i,n,m-k)
            if i<0 or i+k<0: continue
            i+=lcp(i,i+k)
            cur[k]=i
            if k==m-n and i>=n: return "Yes"
        prev=cur
    return "No"
