        minP = [INF] * k
        minP[0] = 0
        P = 0
        ans = -INF
        for j in range(1, len(nums) + 1):
            P += nums[j - 1]
            r = j % k
            if minP[r] != INF:
                v = P - minP[r]
                if v > ans:
                    ans = v
            if P < minP[r]:
                minP[r] = P
        return int(ans)

