            res = set()
            L = len(s)
            for i in range(L):
                for j in range(i + 1, L):
                    t = list(s)
                    t[i], t[j] = t[j], t[i]
                    res.add(int("".join(t)))
            return res

        n = len(nums)
        sw = [one_swaps(v) for v in nums]
        count = 0
        for i in range(n):
            for j in range(i + 1, n):
                x, y = nums[i], nums[j]
                if x == y or y in sw[i] or x in sw[j]:
                    count += 1
        return count

