    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        m = len(queries)
        LIM = max(nums) if nums else 0
        mask = (1 << (LIM + 1)) - 1
        bits = [1] * n  # bit s set => sum s achievable
        for k in range(m + 1):
            if all((bits[i] >> nums[i]) & 1 for i in range(n)):
                return k
            if k == m:
                break
            l, r, v = queries[k]
            for i in range(l, r + 1):
                bits[i] = (bits[i] | (bits[i] << v)) & mask
        return -1

