import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        L = len(str(n))
        LIM = 10 ** L
        sieve = [True] * LIM
        sieve[0] = False
        if LIM > 1:
            sieve[1] = False
        i = 2
        while i * i < LIM:
            if sieve[i]:
                for j in range(i * i, LIM, i):
                    sieve[j] = False
            i += 1
        if sieve[n] or sieve[m]:
            return -1
        INF = float('inf')
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            d, u = heapq.heappop(pq)
            if d != dist.get(u, INF):
                continue
            if u == m:
                return d
            s = str(u).zfill(L)
            for p in range(L):
                dig = int(s[p])
                w = 10 ** (L - 1 - p)
                for nd in (dig + 1, dig - 1):
                    if 0 <= nd <= 9:
                        v = u + (nd - dig) * w
                        if sieve[v]:
                            continue
                        nd_cost = d + v
                        if nd_cost < dist.get(v, INF):
                            dist[v] = nd_cost
                            heapq.heappush(pq, (nd_cost, v))
        return -1

