import numpy as np
class Solution:
    def beautifulSplits(self, nums):
        n = len(nums)
        if n < 3:
            return 0
        z = [0]*n
        z[0] = n
        l = r = 0
        for i in range(1, n):
            if i < r:
                z[i] = min(r-i, z[i-l])
            while i+z[i] < n and nums[z[i]] == nums[i+z[i]]:
                z[i] += 1
            if i+z[i] > r:
                l, r = i, i+z[i]
        arr = np.array(nums, dtype=np.int64)
        prev = np.zeros(n+1, dtype=np.int64)
        total = 0
        for a in range(n-1, -1, -1):
            cur = np.zeros(n+1, dtype=np.int64)
            cur[:n] = (arr == nums[a]) * (prev[1:n+1] + 1)
            prev = cur
            if a < 1 or a > n-2:
                continue
            b = np.arange(a+1, n, dtype=np.int64)
            L = b - a
            m2 = (cur[b] >= L) & (b + L <= n)
            if z[a] >= a:
                m1 = b >= 2*a
            else:
                m1 = np.zeros(len(b), dtype=bool)
            total += int(np.count_nonzero(m1 | m2))
        return total

