import numpy as np

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n, m = len(source), len(pattern)
        NEG = -10**9
        pos = {}
        for j, ch in enumerate(pattern):
            pos.setdefault(ch, []).append(j)
        pos = {k: np.array(v, dtype=np.int64) for k, v in pos.items()}
        is_t = np.zeros(n, dtype=bool)
        for t in targetIndices:
            is_t[t] = True
        dp = np.full(m + 1, NEG, dtype=np.int64)
        dp[0] = 0
        for i in range(n):
            idx = pos.get(source[i])
            if is_t[i]:
                new = dp + 1
            else:
                new = dp.copy()
            if idx is not None:
                new[idx + 1] = np.maximum(new[idx + 1], dp[idx])
            dp = new
        return int(max(dp[m], 0)) if dp[m] > NEG // 2 else 0

