from typing import List
class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        radj = [[] for _ in range(n)]
        for a, b, w in edges:
            radj[b].append((a, w))
        INF = float('inf')
        key = [INF] * n
        key[0] = 0
        pq = [(0, 0)]
        while pq:
            d, x = heapq.heappop(pq)
            if d > key[x]:
                continue
            for u, w in radj[x]:
                nd = max(w, d)
                if nd < key[u]:
                    key[u] = nd
                    heapq.heappush(pq, (nd, u))
        ans = 0
        for v in range(1, n):
            if key[v] == INF:
                return -1
            ans = max(ans, key[v])
        return ans

