class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = float('inf')
        pairs = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = {p: cost[0][p[0]] + cost[n-1][p[1]] for p in pairs}
        for i in range(1, n // 2):
            j = n - 1 - i
            nd = {}
            for (a, b) in pairs:
                best = INF
                for (pa, pb), v in dp.items():
                    if pa != a and pb != b and v < best:
                        best = v
                nd[(a, b)] = best + cost[i][a] + cost[j][b]
            dp = nd
        return int(min(dp.values()))

