class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        from itertools import groupby
        runs = [(k, len(list(g))) for k, g in groupby(s)]
        total = s.count('1')
        best = 0
        for i in range(1, len(runs) - 1):
            if runs[i][0] == '1':
                best = max(best, runs[i - 1][1] + runs[i + 1][1])
        return total + best

