                    continue
                x1, y1 = P[i]
                x2, y2 = P[j]
                if not (x1 < x2 and y1 < y2):
                    continue
                if (x1, y2) not in pts or (x2, y1) not in pts:
                    continue
                ok = True
                for (x, y) in P:
                    if x1 <= x <= x2 and y1 <= y <= y2:
                        if (x, y) in ((x1, y1), (x1, y2), (x2, y1), (x2, y2)):
                            continue
                        ok = False
                        break
                if ok:
                    best = max(best, (x2 - x1) * (y2 - y1))
        return best

